import{_ as a,a as t,c as n,ac as r}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"创建型设计模式","description":"按创建需求区分单个实现选择、整套产品、分步组装、复制起点与共享实例，并保留深浅拷贝和全局状态的边界。","frontmatter":{"title":"创建型设计模式","description":"按创建需求区分单个实现选择、整套产品、分步组装、复制起点与共享实例，并保留深浅拷贝和全局状态的边界。","generated":"consolidation-v2","showdocs":{"topics":[{"id":"patterns","title":"设计模式","link":"/topics/patterns/"},{"id":"go","title":"Go","link":"/topics/go/"}],"kind":"设计意图与对象责任","scope":"general","audience":"general","group":"原理与设计","summary":"按创建需求区分单个实现选择、整套产品、分步组装、复制起点与共享实例，并保留深浅拷贝和全局状态的边界。","status":"active","related":[{"title":"备忘录","link":"/principles/patterns/behavior/memento","kind":"设计意图与对象责任","scope":"general","audience":"general"},{"title":"策略","link":"/principles/patterns/behavior/strategy","kind":"设计意图与对象责任","scope":"general","audience":"general"},{"title":"抽象工厂","link":"/principles/patterns/creation/abstract-factory","kind":"设计意图与对象责任","scope":"general","audience":"general"},{"title":"代理","link":"/principles/patterns/structure/proxy","kind":"设计意图与对象责任","scope":"general","audience":"general"},{"title":"单例","link":"/principles/patterns/creation/singleton","kind":"设计意图与对象责任","scope":"general","audience":"general"}],"prev":{"text":"抽象工厂","link":"/principles/patterns/creation/abstract-factory"},"next":{"text":"单例","link":"/principles/patterns/creation/singleton"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"抽象工厂","link":"/principles/patterns/creation/abstract-factory"},"next":{"text":"单例","link":"/principles/patterns/creation/singleton"}},"headers":[],"relativePath":"principles/patterns/creation/patterns-creation-general-general.md","filePath":"principles/patterns/creation/patterns-creation-general-general.md"}'),i={name:"principles/patterns/creation/patterns-creation-general-general.md"};function s(p,e,o,d,c,l){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="创建型设计模式" tabindex="-1">创建型设计模式 <a class="header-anchor" href="#创建型设计模式" aria-label="Permalink to &quot;创建型设计模式&quot;">​</a></h1><p>本页按场景选择方法；通过各条目链接阅读完整推演、源码和输出。</p><p>前置是结构体、接口与方法；每个 package main 单独保存为新模块的 main.go，不能将五个入口拼接。下文输出为静态推导，本轮未执行。构建器和工厂只演示对象创建；NewSender 对非 sms 的输入全部回退 Email，Build 不做字段校验。</p><table tabindex="0"><thead><tr><th>要解决的问题</th><th>可选方法</th><th>选择前确认</th></tr></thead><tbody><tr><td>按输入选择一个具体实现</td><td>简单工厂</td><td>示例把 Sender 的选择集中在创建函数；种类少且初始化简单时普通构造函数更直接。</td></tr><tr><td>一起创建必须相互匹配的组件</td><td>抽象工厂</td><td>适合产品族切换；增加产品种类需要修改所有工厂接口和实现。</td></tr><tr><td>逐步设置很多可选字段</td><td>建造者</td><td>可在构建阶段表达约束；示例 Build 仅返回对象，字段少时结构体字面量更简单。</td></tr><tr><td>从已有配置复制并只修改少数字段</td><td>原型</td><td>切片、映射和指针的浅拷贝可能共享可变数据；示例额外复制 Tags。</td></tr><tr><td>复用初始化成本高的共享对象</td><td>单例</td><td>sync.Once 保证初始化一次；共享可变状态可能让测试相互影响。</td></tr></tbody></table><h2 id="scene-choose-implementations" tabindex="-1">选择单个实现或一整套匹配组件 <a class="header-anchor" href="#scene-choose-implementations" aria-label="Permalink to &quot;选择单个实现或一整套匹配组件 {#scene-choose-implementations}&quot;">​</a></h2><h3 id="entry-factory-method-90583d28d9" tabindex="-1">简单工厂：按输入选择实现 <a class="header-anchor" href="#entry-factory-method-90583d28d9" aria-label="Permalink to &quot;简单工厂：按输入选择实现 {#entry-factory-method-90583d28d9}&quot;">​</a></h3><p><span id="输出"></span><span id="示例"></span></p><p><span id="entry-factory-method-90583d28d9-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/creation/factory-method">简单工厂：按输入选择实现</a>。</p><p>这里具体是按 kind 分支的简单工厂，不是依赖子类型重写创建方法的经典工厂方法；保留原路径和章节锚点便于查阅。客户端只知道 Sender 接口，具体返回 Email 还是 SMS 由创建函数决定。新增发送渠道时，可以把选择和初始化留在工厂中，而业务流程继续调用 Send。</p><p>实现种类很少且没有初始化差异时，普通构造函数通常更直接。</p><h3 id="entry-abstract-factory-ef06bc2ff0" tabindex="-1">抽象工厂 <a class="header-anchor" href="#entry-abstract-factory-ef06bc2ff0" aria-label="Permalink to &quot;抽象工厂 {#entry-abstract-factory-ef06bc2ff0}&quot;">​</a></h3><p><span id="输出-1"></span><span id="示例-1"></span></p><p><span id="entry-abstract-factory-ef06bc2ff0-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/creation/abstract-factory">抽象工厂</a>。</p><p>代价是增加新产品种类时需要修改所有工厂接口和实现。</p><h2 id="scene-assemble-and-copy" tabindex="-1">分步组装新对象或从已有对象复制 <a class="header-anchor" href="#scene-assemble-and-copy" aria-label="Permalink to &quot;分步组装新对象或从已有对象复制 {#scene-assemble-and-copy}&quot;">​</a></h2><h3 id="entry-builder-f688ceeb44" tabindex="-1">建造者 <a class="header-anchor" href="#entry-builder-f688ceeb44" aria-label="Permalink to &quot;建造者 {#entry-builder-f688ceeb44}&quot;">​</a></h3><p><span id="输出-2"></span><span id="示例-2"></span></p><p><span id="entry-builder-f688ceeb44-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/creation/builder">建造者</a>。</p><p>字段很少且没有校验时，直接使用结构体字面量更符合 Go 的习惯。</p><h3 id="entry-prototype-2d3032d944" tabindex="-1">原型 <a class="header-anchor" href="#entry-prototype-2d3032d944" aria-label="Permalink to &quot;原型 {#entry-prototype-2d3032d944}&quot;">​</a></h3><p><span id="输出-3"></span><span id="示例-3"></span></p><p><span id="entry-prototype-2d3032d944-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/creation/prototype">原型</a>。</p><p>若 Clone 只复制 Tags 的切片描述符而没有复制底层数组，修改克隆体的标签也会影响原对象；本例通过另建切片复制标签，隔离这一层可变数据。</p><h2 id="scene-share-one-instance" tabindex="-1">统一初始化并复用共享实例 <a class="header-anchor" href="#scene-share-one-instance" aria-label="Permalink to &quot;统一初始化并复用共享实例 {#scene-share-one-instance}&quot;">​</a></h2><h3 id="entry-singleton-6ba1880ee6" tabindex="-1">单例 <a class="header-anchor" href="#entry-singleton-6ba1880ee6" aria-label="Permalink to &quot;单例 {#entry-singleton-6ba1880ee6}&quot;">​</a></h3><p><span id="输出-4"></span><span id="示例-4"></span></p><p><span id="entry-singleton-6ba1880ee6-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/creation/singleton">单例</a>。</p><p>单例会引入共享状态，测试时尤其要避免让不同用例相互影响。</p><h2 id="review-exercise" tabindex="-1">静态自检 <a class="header-anchor" href="#review-exercise" aria-label="Permalink to &quot;静态自检 {#review-exercise}&quot;">​</a></h2><p>把原型 Clone 中 Tags 的复制删去，修改克隆标签会怎样？再说明 sync.Once 是否让 Name 后续写入自动安全。提示：区分初始化和使用。</p><details class="details custom-block"><summary>参考解法</summary><p>标签共享底层数组，修改克隆会影响原值；Once 只约束一次初始化，返回对象后同时读写 Name 仍需锁或不可变约定。</p></details>',36)])])}const f=a(i,[["render",s]]);export{b as __pageData,f as default};
